import API from "../shared/axios";

const getAll = (data) => API.get("/api/incoming/get-all", data);
const getByTransactionId = (transactionId) =>
  API.get(`/api/incoming/${transactionId}`);
const getForEntry = (data) => API.get("/api/incoming/get-for-entry", data);
const getForRework = (data) => API.get("/api/incoming/get-for-rework", data);
const getForVerification = (data) =>
  API.get("/api/incoming/get-for-verification", data);
const getErrors = (data) => API.get("/api/incoming/get-errors", data);
const getMyOrders = (data) => API.get("/api/incoming/get-my-orders", data);
const getMyOrdersForRework = (data) =>
  API.get("/api/incoming/get-my-orders-for-rework", data);
const buildArchiveSearchParams = (criteria = {}) =>
  Object.fromEntries(
    Object.entries({
      coreId: criteria?.coreId,
      reference: criteria?.reference,
      receivedDateFrom: criteria?.receivedDateFrom,
      receivedDateTo: criteria?.receivedDateTo,
    }).filter(([, value]) => value !== null && value !== undefined && value !== "")
  );
const searchArchive = (criteria = {}) =>
  API.get("/api/incoming/archive-search", {
    params: buildArchiveSearchParams(criteria),
  });
const getActionLog = async (transactionId) => {
  const requests = [
    () => API.get(`/api/incoming/${transactionId}/action-log`),
    () => API.get(`/api/incoming/${transactionId}/action-logs`),
    () => API.get(`/api/incoming/${transactionId}/history`),
  ];

  let lastNotFoundError = null;

  for (const execute of requests) {
    try {
      return await execute();
    } catch (error) {
      const status = error?.response?.status;
      if (status === 404 || status === 405) {
        lastNotFoundError = error;
        continue;
      }
      throw error;
    }
  }

  throw lastNotFoundError || new Error("Ne postoji endpoint za istoriju izmena.");
};
const updateManualEntryDetails = async (transactionId, payload) => {
  const requests = [
    () => API.put(`/api/incoming/${transactionId}/details`, payload),
    () => API.patch(`/api/incoming/${transactionId}/details`, payload),
    () => API.post(`/api/incoming/${transactionId}/details`, payload),
    () => API.put("/api/incoming/update-details", { transactionId, ...payload }),
    () => API.post("/api/incoming/update-details", { transactionId, ...payload }),
  ];

  let lastNotFoundError = null;

  for (const execute of requests) {
    try {
      return await execute();
    } catch (error) {
      const status = error?.response?.status;
      if (status === 404 || status === 405) {
        lastNotFoundError = error;
        continue;
      }
      throw error;
    }
  }

  throw lastNotFoundError || new Error("Ne postoji endpoint za snimanje detalja.");
};
const returnForCorrection = (transactionId) =>
  API.post(`/api/incoming/${transactionId}/actions/return-for-correction`);
const forceProcessing = (transactionId) =>
  API.post(`/api/incoming/${transactionId}/actions/force-processing`);
const sendForVerification = (transactionId) =>
  API.post(`/api/incoming/${transactionId}/actions/send-for-verification`);
const sendForVerificationReject = (transactionId, payload) =>
  API.post(`/api/incoming/${transactionId}/actions/send-for-verification-reject`, payload);
const sendForVerificationForce = (transactionId) =>
  API.post(`/api/incoming/${transactionId}/actions/send-for-verification-force`);
const approveVerification = (transactionId) =>
  API.post(`/api/incoming/${transactionId}/actions/approve-verification`);
const getManualValidationErrors = (transactionId) =>
  API.get(`/api/incoming/${transactionId}/manual-errors`);

export {
  getAll,
  getByTransactionId,
  getForEntry,
  getForRework,
  getForVerification,
  getErrors,
  getMyOrders,
  getMyOrdersForRework,
  searchArchive,
  getActionLog,
  updateManualEntryDetails,
  returnForCorrection,
  forceProcessing,
  sendForVerification,
  sendForVerificationReject,
  sendForVerificationForce,
  approveVerification,
  getManualValidationErrors,
};

