param(
    [Parameter(Mandatory = $true)]
    [string]$SourceMarkdown,

    [Parameter(Mandatory = $true)]
    [string]$OutputDocx
)

$ErrorActionPreference = "Stop"

function Add-Paragraph {
    param(
        [object]$Document,
        [string]$Text,
        [string]$StyleName = "Normal"
    )

    $paragraph = $Document.Paragraphs.Add()
    $paragraph.Range.Text = $Text
    $paragraph.Range.Style = $StyleName
    $paragraph.Range.InsertParagraphAfter() | Out-Null
    return $paragraph
}

function Normalize-InlineMarkdown {
    param([string]$Text)
    return ($Text -replace "\*\*(.*?)\*\*", '$1' -replace "`([^`]*)`", '$1')
}

$sourcePath = (Resolve-Path -LiteralPath $SourceMarkdown).Path
$outputPath = [System.IO.Path]::GetFullPath($OutputDocx)
$outputDir = [System.IO.Path]::GetDirectoryName($outputPath)
if (-not (Test-Path -LiteralPath $outputDir)) {
    New-Item -ItemType Directory -Path $outputDir | Out-Null
}

$lines = Get-Content -LiteralPath $sourcePath -Encoding UTF8

$word = New-Object -ComObject Word.Application
$word.Visible = $false
$word.DisplayAlerts = 0

try {
    $doc = $word.Documents.Add()
    $selection = $word.Selection

    $doc.PageSetup.TopMargin = $word.CentimetersToPoints(2.2)
    $doc.PageSetup.BottomMargin = $word.CentimetersToPoints(2.2)
    $doc.PageSetup.LeftMargin = $word.CentimetersToPoints(2.4)
    $doc.PageSetup.RightMargin = $word.CentimetersToPoints(2.2)

    $doc.Styles.Item("Normal").Font.Name = "Calibri"
    $doc.Styles.Item("Normal").Font.Size = 10.5
    $doc.Styles.Item("Normal").ParagraphFormat.SpaceAfter = 6
    $doc.Styles.Item("Heading 1").Font.Name = "Calibri Light"
    $doc.Styles.Item("Heading 1").Font.Size = 18
    $doc.Styles.Item("Heading 1").Font.Bold = $true
    $doc.Styles.Item("Heading 1").ParagraphFormat.SpaceBefore = 18
    $doc.Styles.Item("Heading 1").ParagraphFormat.SpaceAfter = 8
    $doc.Styles.Item("Heading 2").Font.Name = "Calibri"
    $doc.Styles.Item("Heading 2").Font.Size = 14
    $doc.Styles.Item("Heading 2").Font.Bold = $true
    $doc.Styles.Item("Heading 2").ParagraphFormat.SpaceBefore = 12
    $doc.Styles.Item("Heading 2").ParagraphFormat.SpaceAfter = 6
    $doc.Styles.Item("Heading 3").Font.Name = "Calibri"
    $doc.Styles.Item("Heading 3").Font.Size = 12
    $doc.Styles.Item("Heading 3").Font.Bold = $true
    $doc.Styles.Item("Heading 3").ParagraphFormat.SpaceBefore = 8
    $doc.Styles.Item("Heading 3").ParagraphFormat.SpaceAfter = 4

    Add-Paragraph -Document $doc -Text "CBR tehnicka dokumentacija" -StyleName "Title" | Out-Null
    Add-Paragraph -Document $doc -Text "Central Bank Reporting" -StyleName "Subtitle" | Out-Null
    Add-Paragraph -Document $doc -Text "Kompletna tehnicka dokumentacija sistema" -StyleName "Normal" | Out-Null
    Add-Paragraph -Document $doc -Text "Verzija: 1.0" -StyleName "Normal" | Out-Null
    Add-Paragraph -Document $doc -Text ("Datum: " + (Get-Date -Format "dd.MM.yyyy.")) -StyleName "Normal" | Out-Null

    $selection.EndKey(6) | Out-Null
    $selection.InsertBreak(7) | Out-Null

    Add-Paragraph -Document $doc -Text "Sadrzaj" -StyleName "Heading 1" | Out-Null
    $tocRange = $selection.Range
    $doc.TablesOfContents.Add($tocRange, $true, 1, 3) | Out-Null
    $selection.EndKey(6) | Out-Null
    $selection.InsertBreak(7) | Out-Null

    $skipManualToc = $false
    foreach ($line in $lines) {
        $trim = $line.Trim()

        if ($trim -eq "# CBR tehnicka dokumentacija") {
            continue
        }

        if ($trim -eq "## Sadrzaj") {
            $skipManualToc = $true
            continue
        }

        if ($skipManualToc) {
            if ($trim -match "^##\s+\d+\.") {
                $skipManualToc = $false
            } else {
                continue
            }
        }

        if ([string]::IsNullOrWhiteSpace($trim)) {
            continue
        }

        if ($trim -match "^####\s+(.+)$") {
            Add-Paragraph -Document $doc -Text (Normalize-InlineMarkdown $Matches[1]) -StyleName "Heading 3" | Out-Null
            continue
        }

        if ($trim -match "^###\s+(.+)$") {
            Add-Paragraph -Document $doc -Text (Normalize-InlineMarkdown $Matches[1]) -StyleName "Heading 2" | Out-Null
            continue
        }

        if ($trim -match "^##\s+(.+)$") {
