        if ($trim -match "^###\s+(.+)$") {
            Add-Paragraph -Document $doc -Text (Normalize-InlineMarkdown $Matches[1]) -StyleName "Heading 2" | Out-Null
            continue
        }

        if ($trim -match "^##\s+(.+)$") {
            Add-Paragraph -Document $doc -Text (Normalize-InlineMarkdown $Matches[1]) -StyleName "Heading 1" | Out-Null
            continue
        }

        if ($trim -match "^-\s+(.+)$") {
            Add-Paragraph -Document $doc -Text (Normalize-InlineMarkdown $Matches[1]) -StyleName "List Bullet" | Out-Null
            continue
        }

        if ($trim -match "^\d+\.\s+(.+)$") {
            Add-Paragraph -Document $doc -Text (Normalize-InlineMarkdown $Matches[1]) -StyleName "List Number" | Out-Null
            continue
        }

        Add-Paragraph -Document $doc -Text (Normalize-InlineMarkdown $trim) -StyleName "Normal" | Out-Null
    }

    foreach ($toc in $doc.TablesOfContents) {
        $toc.Update()
    }

    if (Test-Path -LiteralPath $outputPath) {
        Remove-Item -LiteralPath $outputPath -Force
    }

    $doc.SaveAs([ref]$outputPath, [ref]16)
    $doc.Close()
}
finally {
    $word.Quit()
    [System.Runtime.InteropServices.Marshal]::ReleaseComObject($word) | Out-Null
}

