import React, { useEffect, useMemo, useState } from "react";
import { InfoCircleOutlined } from "@ant-design/icons";
import Action from "./Action";
import Statistic from "./Statistic";
import styles from "./Drawer.module.css";

const toEditableText = (value) =>
  value === null || value === undefined ? "" : String(value);

const isBlankText = (value) =>
  value === null || value === undefined || String(value).trim() === "";

const createEmptyRegulatoryDetail = (keySuffix = Date.now()) => ({
  id: null,
  localKey: `new-row-${keySuffix}`,
  splitStatCode: "",
  splitAmount: "",
  invoiceNumber: "",
  invoiceYear: "",
  splitAmountCurrency: "",
  isNew: true,
});

const isRegulatoryDetailEmpty = (detail = {}) =>
  isBlankText(detail?.splitStatCode) &&
  isBlankText(detail?.splitAmount) &&
  isBlankText(detail?.invoiceNumber) &&
  isBlankText(detail?.invoiceYear) &&
  isBlankText(detail?.splitAmountCurrency);

const removeTransientEmptyRows = (rows = []) =>
  rows.filter((detail) => !(detail?.isNew && !detail?.id && isRegulatoryDetailEmpty(detail)));

const mapRegulatoryDetailsToEditable = (rawOrder = {}) => {
  const details = Array.isArray(rawOrder?.regulatoryDetails)
    ? rawOrder.regulatoryDetails
    : [];

  return details.map((detail = {}, index) => ({
    id: detail?.id ?? null,
    localKey: detail?.id ?? `detail-${index}`,
    splitStatCode: toEditableText(detail?.splitStatCode),
    splitAmount: toEditableText(detail?.splitAmount),
    invoiceNumber: toEditableText(detail?.invoiceNumber),
    invoiceYear: toEditableText(detail?.invoiceYear),
    splitAmountCurrency: toEditableText(detail?.splitAmountCurrency),
    isNew: false,
  }));
};

const mapRawOrderToEditable = (rawOrder = {}) => ({
  reportType: toEditableText(rawOrder?.reportType),
  paymentInstrument: toEditableText(rawOrder?.paymentInstrument),
  specialMark: toEditableText(rawOrder?.specialMark),
  countryCode1: toEditableText(rawOrder?.countryCode1),
  drStatisticalCode: toEditableText(rawOrder?.drStatisticalCode),
  customerId: toEditableText(rawOrder?.customerId),
  countryCode2: toEditableText(rawOrder?.countryCode2),
  crStatisticalCode: toEditableText(rawOrder?.crStatisticalCode),
  loanNumber: toEditableText(rawOrder?.loanNumber),
  loanYear: toEditableText(rawOrder?.loanYear),
  customerStp: toEditableText(rawOrder?.customerStp ?? rawOrder?.stp),
  split: toEditableText(rawOrder?.split),
  regulatoryDetails: mapRegulatoryDetailsToEditable(rawOrder),
});

const Details = ({
  rawOrder,
  validationErrors,
  onReturnForCorrection,
  onForceProcessing,
  onSendForVerification,
  onApproveVerification,
  onRestoreFromError,
  onSendForVerificationReject,
  onDetailsDraftChange,
  transactionStatusCode,
  canEditDetails,
  actionPermissions,
  actionsDisabled,
  isReturning,
  isForcing,
  isSendingForVerification,
  isApprovingVerification,
  isRestoringFromError,
  isSendingForVerificationReject,
}) => {
  const [formValues, setFormValues] = useState(() => mapRawOrderToEditable(rawOrder));
  const [initialSnapshot, setInitialSnapshot] = useState(() =>
    JSON.stringify(mapRawOrderToEditable(rawOrder))
  );

  useEffect(() => {
    const mapped = mapRawOrderToEditable(rawOrder);
    setFormValues(mapped);
    setInitialSnapshot(JSON.stringify(mapped));
  }, [rawOrder]);

  const hasChanges = useMemo(
    () => JSON.stringify(formValues) !== initialSnapshot,
    [formValues, initialSnapshot]
  );

  useEffect(() => {
    if (typeof onDetailsDraftChange === "function") {
      onDetailsDraftChange(formValues, hasChanges);
    }
  }, [formValues, hasChanges, onDetailsDraftChange]);

  const renderFieldLabel = (text) => (
    <label className={styles.detailFieldLabel}>
      {text}
      {"\u00A0"}
      <InfoCircleOutlined />
      {"\u00A0"}:
    </label>
  );

  const handleFieldChange = (field) => (event) => {
    if (!canEditDetails) {
      return;
    }

    const value = event?.target?.value ?? "";
    setFormValues((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const handleRegulatoryDetailChange = (index, field, value) => {
    if (!canEditDetails) {
      return;
    }

    setFormValues((current) => {
      const rows = Array.isArray(current?.regulatoryDetails)
        ? [...current.regulatoryDetails]
        : [];

      if (rows.length === 0) {
        rows.push(createEmptyRegulatoryDetail("auto-0"));
      }
      while (rows.length <= index) {
        rows.push(createEmptyRegulatoryDetail(`auto-${rows.length}`));
      }

      rows[index] = {
        ...rows[index],
        [field]: value,
      };

      const cleanedRows = removeTransientEmptyRows(rows);

      return {
        ...current,
        regulatoryDetails: cleanedRows,
      };
    });
  };

  const handleDeleteRegulatoryRow = (index) => {
    if (!canEditDetails) {
      return;
    }

    setFormValues((current) => {
      const rows = Array.isArray(current?.regulatoryDetails)
        ? [...current.regulatoryDetails]
        : [];

      if (index < 0 || index >= rows.length) {
        return current;
      }

      rows.splice(index, 1);

      return {
        ...current,
        regulatoryDetails: rows,
      };
    });
  };

  const handleAddRegulatoryRow = () => {
    if (!canEditDetails) {
      return;
    }

    setFormValues((current) => {
      const rows = Array.isArray(current?.regulatoryDetails)
        ? removeTransientEmptyRows([...current.regulatoryDetails])
        : [];
      const nextIndex = rows.length;
      rows.push(createEmptyRegulatoryDetail(`${Date.now()}-${nextIndex}`));

      return {
        ...current,
        regulatoryDetails: rows,
      };
    });
  };

  const handleStatisticPrimaryAction = () => {
    if (!canEditDetails) {
      return;
    }
    handleAddRegulatoryRow();
  };

  const renderInput = (field, { alwaysDisabled = false } = {}) => (
    <input
      className={styles.detailInput}
      value={toEditableText(formValues?.[field])}
      onChange={handleFieldChange(field)}
      readOnly={alwaysDisabled || !canEditDetails}
      disabled={alwaysDisabled}
    />
  );

  const renderFormField = (field, label, className) => (
    <div className={`${styles.detailField} ${className}`}>
      {renderFieldLabel(label)}
      {renderInput(field)}
    </div>
  );

  return (
    <div className={styles.rightColumn}>
      <section className={`${styles.panel} ${styles.rightPanel}`}>
        <h3 className={styles.panelTitle}>Detalji</h3>

        <div className={styles.detailsFormGrid}>
          {renderFormField("reportType", "Slog", styles.detailFieldReportType)}
          {renderFormField(
            "paymentInstrument",
            "Instrument",
            styles.detailFieldPaymentInstrument
          )}
          {renderFormField("specialMark", "Posebna oznaka", styles.detailFieldSpecialMark)}
          {renderFormField("customerId", "Maticni broj", styles.detailFieldCustomerId)}
          {renderFormField(
            "countryCode1",
            "Zemlja nerezidenta",
            styles.detailFieldCountryCode1
          )}
          {renderFormField(
            "countryCode2",
            "Zemlja ino partnera",
            styles.detailFieldCountryCode2
          )}
          {renderFormField(
            "drStatisticalCode",
            "DR sifra osnova",
            styles.detailFieldDrStatisticalCode
          )}
          {renderFormField(
            "crStatisticalCode",
            "CR sifra osnova",
            styles.detailFieldCrStatisticalCode
          )}
          {renderFormField("loanNumber", "Broj kredita", styles.detailFieldLoanNumber)}
          {renderFormField("loanYear", "Godina kredita", styles.detailFieldLoanYear)}
        </div>

        <Statistic
          regulatoryDetails={formValues?.regulatoryDetails || []}
          editable={canEditDetails}
          onChangeRow={handleRegulatoryDetailChange}
          onDeleteRow={handleDeleteRegulatoryRow}
          onPrimaryAction={handleStatisticPrimaryAction}
        />
      </section>

      <Action
        validationErrors={validationErrors}
        onReturnForCorrection={onReturnForCorrection}
        onForceProcessing={onForceProcessing}
        onSendForVerification={onSendForVerification}
        onApproveVerification={onApproveVerification}
        onRestoreFromError={onRestoreFromError}
        onSendForVerificationReject={onSendForVerificationReject}
        transactionStatusCode={transactionStatusCode}
        actionPermissions={actionPermissions}
        actionsDisabled={actionsDisabled}
        isReturning={isReturning}
        isForcing={isForcing}
        isSendingForVerification={isSendingForVerification}
        isApprovingVerification={isApprovingVerification}
        isRestoringFromError={isRestoringFromError}
        isSendingForVerificationReject={isSendingForVerificationReject}
      />
    </div>
  );
};

export default Details;

