        CBR_TRANSACTION_ID,
        REQUEST_ID,
        CALL_REPLY_REF,
        S10_AT
    )
    WITH last_s10 AS (
        SELECT s.cbr_transaction_id,
               MAX(s.created_at) AS s10_at
