package rs.unicredit.cbr.service;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.time.LocalDateTime;
import java.util.Optional;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.server.ResponseStatusException;

import rs.unicredit.cbr.dto.TransactionLockResponse;
import rs.unicredit.cbr.model.CbrTransactionLock;
import rs.unicredit.cbr.repository.CbrTransactionLockRepository;
import rs.unicredit.cbr.repository.CbrTransactionRepository;

@ExtendWith(MockitoExtension.class)
class TransactionLockServiceTest {

    @Mock
    private CbrTransactionLockRepository transactionLockRepository;

    @Mock
    private CbrTransactionRepository transactionRepository;

    @Mock
    private CurrentUserService currentUserService;

    @InjectMocks
    private TransactionLockService service;

    @BeforeEach
    void setUp() {
        ReflectionTestUtils.setField(service, "lockTtlSeconds", 60L);
    }

    @Test
    void acquireCreatesNewLockWhenNoneExists() {
        when(transactionRepository.existsById(5L)).thenReturn(true);
        when(currentUserService.getUsername()).thenReturn("john");
        when(transactionLockRepository.findById(5L)).thenReturn(Optional.empty());
        when(transactionLockRepository.save(any(CbrTransactionLock.class))).thenAnswer(invocation -> invocation.getArgument(0));

        TransactionLockResponse response = service.acquire(5L, "sess-1");

        ArgumentCaptor<CbrTransactionLock> captor = ArgumentCaptor.forClass(CbrTransactionLock.class);
        verify(transactionLockRepository).save(captor.capture());
        assertThat(captor.getValue().getLockedBy()).isEqualTo("john");
        assertThat(captor.getValue().getSessionId()).isEqualTo("sess-1");
        assertThat(response.isLocked()).isTrue();
        assertThat(response.isOwnedByCurrentUser()).isTrue();
    }

    @Test
    void refreshRejectsDifferentSession() {
        when(currentUserService.getUsername()).thenReturn("john");
        when(transactionLockRepository.findById(8L)).thenReturn(Optional.of(CbrTransactionLock.builder()
                .transactionId(8L)
                .lockedBy("john")
                .sessionId("sess-1")
                .lockedAt(LocalDateTime.now())
                .expiresAt(LocalDateTime.now().plusMinutes(1))
                .build()));

        assertThatThrownBy(() -> service.refresh(8L, "sess-2"))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> assertThat(((ResponseStatusException) ex).getStatusCode()).isEqualTo(HttpStatus.CONFLICT));
    }

    @Test
    void releaseReturnsUnlockedWhenNoActiveLockExists() {
        when(currentUserService.getUsername()).thenReturn("john");
        when(transactionLockRepository.findById(9L)).thenReturn(Optional.empty());

        TransactionLockResponse response = service.release(9L, "sess");

        assertThat(response.isLocked()).isFalse();
        verify(transactionLockRepository, never()).delete(any());
    }

    @Test
    void assertCanMutateThrowsWhenLockBelongsToAnotherUser() {
        when(currentUserService.getUsername()).thenReturn("john");
        when(transactionLockRepository.findById(11L)).thenReturn(Optional.of(CbrTransactionLock.builder()
                .transactionId(11L)
                .lockedBy("mary")
                .sessionId("sess-1")
                .lockedAt(LocalDateTime.now())
                .expiresAt(LocalDateTime.now().plusMinutes(1))
                .build()));

        assertThatThrownBy(() -> service.assertCanMutate(11L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException response = (ResponseStatusException) ex;
                    assertThat(response.getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
                    assertThat(response.getReason()).contains("TX_LOCKED::mary");
                });
    }
}

