package rs.unicredit.cbr.service.impl;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import rs.unicredit.cbr.dto.ActionLogDto;
import rs.unicredit.cbr.mapper.ActionLogMapper;
import rs.unicredit.cbr.model.CbrActionLog;
import rs.unicredit.cbr.repository.ActionLogRepository;
import rs.unicredit.cbr.service.CurrentUserService;

@ExtendWith(MockitoExtension.class)
class ActionLogServiceImplTest {

    @Mock
    private ActionLogRepository actionLogRepository;

    @Mock
    private ActionLogMapper actionLogMapper;

    @Mock
    private CurrentUserService currentUserService;

    @InjectMocks
    private ActionLogServiceImpl service;

    @Test
    void logActionCreatesEntryWithCurrentUser() {
        ActionLogDto expected = ActionLogDto.builder().requestId("1").username("john").action("ACT").build();
        when(currentUserService.getUsername()).thenReturn("john");
        when(actionLogMapper.toEntity(org.mockito.ArgumentMatchers.any(ActionLogDto.class))).thenReturn(new CbrActionLog());
        when(actionLogRepository.save(org.mockito.ArgumentMatchers.any(CbrActionLog.class))).thenReturn(new CbrActionLog());
        when(actionLogMapper.toDto(org.mockito.ArgumentMatchers.any(CbrActionLog.class))).thenReturn(expected);

        ActionLogDto result = service.logAction(" 1 ", " ACT ", Map.of("a", 1));

        assertThat(result).isEqualTo(expected);
        verify(actionLogMapper).toEntity(org.mockito.ArgumentMatchers.argThat(dto ->
                "1".equals(dto.getRequestId())
                        && "john".equals(dto.getUsername())
                        && "ACT".equals(dto.getAction())
                        && Integer.valueOf(1).equals(dto.getChanges().get("a"))));
    }

    @Test
    void logActionFallsBackToSystemUser() {
        when(currentUserService.getUsername()).thenThrow(new RuntimeException("no auth"));
        when(actionLogMapper.toEntity(org.mockito.ArgumentMatchers.any(ActionLogDto.class))).thenReturn(new CbrActionLog());
        when(actionLogRepository.save(org.mockito.ArgumentMatchers.any(CbrActionLog.class))).thenReturn(new CbrActionLog());
        when(actionLogMapper.toDto(org.mockito.ArgumentMatchers.any(CbrActionLog.class))).thenReturn(new ActionLogDto());

        service.logAction("1", "ACT", null);

        verify(actionLogMapper).toEntity(org.mockito.ArgumentMatchers.argThat(dto ->
                "SYSTEM".equals(dto.getUsername()) && dto.getChanges().isEmpty()));
    }

    @Test
    void getAllByRequestIdReturnsEmptyForBlankRequestId() {
        assertThat(service.getAllByRequestId(" ")).isEmpty();
    }

    @Test
    void logActionRejectsBlankRequestId() {
        assertThatThrownBy(() -> service.logAction(" ", "ACT", Map.of()))
                .isInstanceOf(IllegalArgumentException.class);
    }
}

