@Setter
@Builder
@ToString(exclude = "transaction")
@JsonIgnoreProperties(ignoreUnknown = true)
public class CbrTransactionStat implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @GeneratedValue(generator = "cbrTransactionStatSeq", strategy = GenerationType.SEQUENCE)
    @SequenceGenerator(name = "cbrTransactionStatSeq", sequenceName = "TBL_CBR_TRANSACTION_STAT_SEQ", allocationSize = 1)
    private Long id;

    @ManyToOne(optional = false)
    @JoinColumn(name = "CALL_REPLY_REF", referencedColumnName = "CALL_REPLY_REF", nullable = false)
    @JsonBackReference
    private CbrTransaction transaction;

    @Column(name = "SPLIT_STAT_CODE", length = 35)
    private String splitStatCode;

    @Column(name = "SPLIT_AMOUNT", precision = 18, scale = 2)
    private BigDecimal splitAmount;

    @Column(name = "SPLIT_AMOUNT_CCY", length = 3)
    private String splitAmountCurrency;

    @Column(name = "INVOICE_NUMBER", length = 35)
    private String invoiceNumber;

    @Column(name = "INVOICE_YEAR", length = 4)
    private String invoiceYear;

    @Column(name = "CREATED_AT")
    private LocalDateTime createdAt;

    @PrePersist
    public void prePersist() {
        createdAt = createdAt == null ? LocalDateTime.now() : createdAt;
        invoiceNumber = normalizeInvoiceNumber(invoiceNumber);
        invoiceYear = normalizeInvoiceYear(invoiceYear);
    }

    public void setInvoiceNumber(String invoiceNumber) {
        this.invoiceNumber = normalizeInvoiceNumber(invoiceNumber);
    }

    public void setInvoiceYear(String invoiceYear) {
        this.invoiceYear = normalizeInvoiceYear(invoiceYear);
    }

    public boolean isEffectivelyEmpty() {
        return isZeroLike(splitStatCode)
                && isZeroLike(splitAmountCurrency)
                && isZeroLike(invoiceNumber)
                && isZeroLike(invoiceYear)
                && (splitAmount == null || splitAmount.compareTo(BigDecimal.ZERO) == 0);
    }

    private boolean isZeroLike(String value) {
        if (value == null) {
            return true;
        }
        String trimmed = value.trim();
        if (trimmed.isEmpty()) {
            return true;
        }
        String normalized = trimmed.toUpperCase(Locale.ROOT);
        if ("NULL".equals(normalized) || "NOTPROVIDED".equals(normalized)) {
            return true;
        }
        for (int i = 0; i < trimmed.length(); i++) {
            char ch = trimmed.charAt(i);
            if (ch != '0') {
                return false;
            }
        }
        return true;
    }

    private String normalizeInvoiceNumber(String value) {
        return isZeroLike(value) ? null : value;
    }

    private String normalizeInvoiceYear(String value) {
