package rs.unicredit.cbr.service.impl;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyMap;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import rs.unicredit.cbr.dto.CbrTransactionDTO;
import rs.unicredit.cbr.dto.ManualEntryDetailsUpdateRequest;
import rs.unicredit.cbr.mapper.CbrTransactionDtoMapper;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.model.TransferDirection;
import rs.unicredit.cbr.repository.CbrTransactionArchiveRepository;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.IncomingRepository;
import rs.unicredit.cbr.repository.OutgoingRepository;
import rs.unicredit.cbr.service.ActionLogService;
import rs.unicredit.cbr.service.CbrRejectService;
import rs.unicredit.cbr.service.CbrStageService;
import rs.unicredit.cbr.service.CurrentUserService;
import rs.unicredit.cbr.service.ManualValidationErrorsService;
import rs.unicredit.cbr.service.MessageOrchestrationService;
import rs.unicredit.cbr.service.RequestErrorListingService;
import rs.unicredit.cbr.service.StageTransitionService;
import rs.unicredit.cbr.service.ValidationEvaluationService;

@ExtendWith(MockitoExtension.class)
class ManualEntryDetailsSuspiciousFlagUpdateTest {

    @Mock
    private IncomingRepository incomingRepository;

    @Mock
    private OutgoingRepository outgoingRepository;

    @Mock
    private CbrTransactionRepository cbrTransactionRepository;

    @Mock
    private CbrTransactionArchiveRepository cbrTransactionArchiveRepository;

    @Mock
    private CbrStageService cbrStageService;

    @Mock
    private CurrentUserService currentUserService;

    @Mock
    private CbrTransactionDtoMapper transactionDtoMapper;

    @Mock
    private ActionLogService actionLogService;

    @Mock
    private CbrRejectService cbrRejectService;

    @Mock
    private StageTransitionService stageTransitionService;

    @Mock
    private ValidationEvaluationService validationEvaluationService;

    @Mock
    private MessageOrchestrationService messageOrchestrationService;

    @Mock
    private ManualValidationErrorsService manualValidationErrorsService;

    @Mock
    private RequestErrorListingService requestErrorListingService;

    @InjectMocks
    private IncomingServiceImpl incomingService;

    @InjectMocks
    private OutgoingServiceImpl outgoingService;

    @Test
    void incomingManualDetailsUpdatePersistsSuspiciousFlagAndLogsAuditChange() {
        CbrTransaction transaction = buildTransaction(11L, 101L, TransferDirection.IN, "N");
        ManualEntryDetailsUpdateRequest request = ManualEntryDetailsUpdateRequest.builder()
                .suspiciousFlag("Y")
                .build();

        when(cbrTransactionRepository.findWithRegulatoryDetailsById(11L)).thenReturn(Optional.of(transaction));
        when(cbrStageService.getStageShortNamesByCode()).thenReturn(Map.of());
        when(transactionDtoMapper.toDto(eq(transaction), anyMap())).thenReturn(new CbrTransactionDTO());
        when(currentUserService.getUsername()).thenReturn("john");

        incomingService.updateManualEntryDetails(11L, request);

        assertThat(transaction.getSuspiciousFlag()).isEqualTo("Y");
        assertThat(transaction.getOrderSubmittedBy()).isEqualTo("john");
        verify(cbrTransactionRepository).save(transaction);

        ArgumentCaptor<Map<String, Object>> changesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(actionLogService).logAction(eq("101"), eq("MANUAL_ENTRY_UPDATE"), changesCaptor.capture());
        assertThat(changesCaptor.getValue())
                .containsEntry("suspiciousFlag_from", "N")
                .containsEntry("suspiciousFlag_to", "Y");
    }

    @Test
    void outgoingManualDetailsUpdatePersistsSuspiciousFlagAndLogsAuditChange() {
        CbrTransaction transaction = buildTransaction(12L, 102L, TransferDirection.OUT, "N");
        ManualEntryDetailsUpdateRequest request = ManualEntryDetailsUpdateRequest.builder()
                .suspiciousFlag("y")
                .build();

        when(cbrTransactionRepository.findWithRegulatoryDetailsById(12L)).thenReturn(Optional.of(transaction));
        when(cbrStageService.getStageShortNamesByCode()).thenReturn(Map.of());
        when(transactionDtoMapper.toDto(eq(transaction), anyMap())).thenReturn(new CbrTransactionDTO());
        when(currentUserService.getUsername()).thenReturn("mary");

        outgoingService.updateManualEntryDetails(12L, request);

        assertThat(transaction.getSuspiciousFlag()).isEqualTo("Y");
        assertThat(transaction.getOrderSubmittedBy()).isEqualTo("mary");
        verify(cbrTransactionRepository).save(transaction);

        ArgumentCaptor<Map<String, Object>> changesCaptor = ArgumentCaptor.forClass(Map.class);
        verify(actionLogService).logAction(eq("102"), eq("MANUAL_ENTRY_UPDATE"), changesCaptor.capture());
        assertThat(changesCaptor.getValue())
                .containsEntry("suspiciousFlag_from", "N")
                .containsEntry("suspiciousFlag_to", "Y");
    }

    private CbrTransaction buildTransaction(
            Long transactionId,
            Long requestId,
            TransferDirection direction,
            String suspiciousFlag) {
        CbrTransactionRequest request = new CbrTransactionRequest();
        request.setId(requestId);

        return CbrTransaction.builder()
                .id(transactionId)
                .request(request)
                .callReplyRef("CALL-" + transactionId)
                .direction(direction)
                .suspiciousFlag(suspiciousFlag)
                .regulatoryDetails(new ArrayList<>())
                .build();
    }
}

