    private void normalizePersistedFields() {
        debtorPostalAddress = truncate(debtorPostalAddress, 256);
        creditorPostalAddress = truncate(creditorPostalAddress, 256);
    }

    private String truncate(String value, int maxLength) {
        if (value == null || value.length() <= maxLength) {
            return value;
        }
        return value.substring(0, maxLength);
    }

    private void normalizeRegulatoryDetails() {
        if (regulatoryDetails == null || regulatoryDetails.isEmpty()) {
            return;
        }
        regulatoryDetails.removeIf(stat -> stat == null || stat.isEffectivelyEmpty());
        for (CbrTransactionStat stat : regulatoryDetails) {
            if (stat.getTransaction() != this) {
                stat.setTransaction(this);
            }
        }
    }
