import React, { useEffect, useState } from "react";
import { Input, Modal, Switch } from "antd";
import { DownOutlined, PlusOutlined } from "@ant-design/icons";
import { useTranslation } from "react-i18next";
import styles from "./Drawer.module.css";

const NOTES_VISIBLE_LIMIT = 3;

const Notice = ({
  notes,
  suspiciousFlag,
  canEditSuspiciousFlag,
  onToggleSuspiciousFlag,
  onAddNote,
  isSavingNote,
  canAddNote,
  selectedOrderKey,
}) => {
  const { t } = useTranslation(["common"]);
  const [isNoteModalOpen, setIsNoteModalOpen] = useState(false);
  const [noteDescription, setNoteDescription] = useState("");
  const [notesExpanded, setNotesExpanded] = useState(false);
  const isSuspicious = String(suspiciousFlag || "").trim().toUpperCase() === "Y";
  const hasNotes = Array.isArray(notes) && notes.length > 0;
  const hiddenNotesCount = hasNotes
    ? Math.max(notes.length - NOTES_VISIBLE_LIMIT, 0)
    : 0;
  const shouldShowMoreNotesButton = hiddenNotesCount > 0;
  const visibleNotes = hasNotes
    ? notesExpanded
      ? notes
      : notes.slice(0, NOTES_VISIBLE_LIMIT)
    : [];

  useEffect(() => {
    setNotesExpanded(false);
  }, [selectedOrderKey]);

  const openNoteModal = () => {
    if (!canAddNote) return;
    setIsNoteModalOpen(true);
  };

  const closeNoteModal = () => {
    setIsNoteModalOpen(false);
    setNoteDescription("");
  };

  const handleSaveNote = async () => {
    const description = noteDescription.trim();
    if (!description || !onAddNote) return;

    const saved = await onAddNote(description);
    if (saved) {
      closeNoteModal();
    }
  };

  return (
    <section className={styles.panel}>
      <div
        className={`${styles.suspiciousFlagSummary} ${
          isSuspicious ? styles.suspiciousFlagSummaryActive : ""
        }`}
      >
        <span className={styles.suspiciousFlagSummaryLabel}>
          {t("common:suspiciousTransaction", {
            defaultValue: "Sumnjiva transakcija",
          })}
        </span>
        <Switch
          checked={isSuspicious}
          onChange={onToggleSuspiciousFlag}
          disabled={!canEditSuspiciousFlag}
          checkedChildren={t("common:suspiciousTransactionYes", { defaultValue: "Da" })}
          unCheckedChildren={t("common:suspiciousTransactionNo", { defaultValue: "Ne" })}
        />
      </div>

      <div className={styles.panelHeader}>
        <h3 className={styles.panelTitle}>Beleske</h3>
        <button
          type="button"
          className={styles.addLinkButton}
          onClick={openNoteModal}
          disabled={!canAddNote}
        >
          <PlusOutlined />
          <span>Dodaj belesku</span>
        </button>
      </div>

      <div className={styles.notesList}>
        {!hasNotes && <p className={styles.noteText}>Nema beleski.</p>}

        {hasNotes &&
          visibleNotes.map((note) => (
            <article key={note.id} className={styles.noteItem}>
              <div className={styles.noteMeta}>
                <span className={styles.noteAuthor}>{note.author}</span>
                <span className={styles.noteDate}>{note.date}</span>
              </div>
              <p className={styles.noteText}>{note.text}</p>
            </article>
          ))}
      </div>

      {shouldShowMoreNotesButton && (
        <button
          type="button"
          className={styles.moreButton}
          onClick={() => setNotesExpanded((current) => !current)}
        >
          <DownOutlined />
          <span>{notesExpanded ? "Prikazi manje" : `Prikazi jos ${hiddenNotesCount}`}</span>
        </button>
      )}

      <Modal
        title="Dodaj belesku"
        open={isNoteModalOpen}
        onCancel={closeNoteModal}
        onOk={handleSaveNote}
        okText="Sacuvaj"
        cancelText="Odustani"
        okButtonProps={{
          disabled: !noteDescription.trim(),
          loading: isSavingNote,
        }}
