          defaultValue: "Transakcija je zakljucana za izmenu.",
        }),
        "error"
      );
      return false;
    }

    setIsSavingDetails(true);
    const payload = mapEditableFormToPayload(formValues);

    try {
      const response = await transactionApi.updateManualEntryDetails(transactionId, payload);
      const responseData =
        response?.data && typeof response.data === "object" ? response.data : {};

      const mergedRawOrder = normalizeOrderForDrawer({
        ...rawOrder,
        ...payload,
        ...responseData,
      });

      setEditableOrder(mergedRawOrder);
      setDetailsDraft(mapRawOrderToEditableForm(mergedRawOrder));
      setHasDetailsChanges(false);
      setActionValidationErrors([]);
      setManualValidationErrors([]);
      notifyOrderUpdated(mergedRawOrder);
      notifyDrawer("Uspeh", "Detalji su uspesno sacuvani.", "success");
      return true;
    } catch (error) {
      const actionErrorCode = parseActionErrorCode(error);
      if (actionErrorCode === TX_LOCKED_CODE) {
        setIsLockBlocked(true);
        notifyLockedByOtherUser(parseLockOwner(error));
        return false;
      }
      notifyDrawer("Greska", "Neuspesno snimanje detalja.", "error");
      return false;
    } finally {
      setIsSavingDetails(false);
    }
  };

  const handleDetailsDraftChange = useCallback((values, hasChanges) => {
    setDetailsDraft((current) => {
      const suspiciousFlag =
        current?.suspiciousFlag ??
        mapRawOrderToEditableForm(rawOrder)?.suspiciousFlag;
      const nextDraft = {
        ...(values || {}),
        suspiciousFlag,
      };

      if (JSON.stringify(current || {}) === JSON.stringify(nextDraft)) {
        return current;
      }

      return nextDraft;
    });

    setHasDetailsChanges(Boolean(hasChanges));
  }, [rawOrder]);

  const handleSuspiciousFlagToggle = useCallback((checked) => {
    const normalizedFlag = checked ? "Y" : "N";

    setDetailsDraft((current) => {
      const baseDraft = current || mapRawOrderToEditableForm(rawOrder);
      if (baseDraft?.suspiciousFlag === normalizedFlag) {
        return current;
      }

      const nextDraft = {
        ...baseDraft,
        suspiciousFlag: normalizedFlag,
      };

      setHasDetailsChanges(hasDraftChangesComparedToPersisted(selectedOrder, nextDraft));
      return nextDraft;
    });
  }, [rawOrder, selectedOrder]);

  const handleDrawerClose = async () => {
    if (isSavingDetails) {
      return;
    }

    if (canEditDetails && hasDetailsChanges) {
      const shouldSave = await askSaveChangesConfirmation(t);
      if (shouldSave) {
        const valuesToSave = detailsDraft || mapRawOrderToEditableForm(rawOrder);
        const saved = await handleSaveDetails(valuesToSave);
        if (!saved) {
          return;
        }
      } else {
        resetToPersistedDetailsState(
          selectedOrder,
          setEditableOrder,
          setDetailsDraft,
          setHasDetailsChanges
        );
      }
    }

    await releaseDrawerLock();
    onClose();
  };

  return (
    <AntDrawer
      open={open}
      onClose={handleDrawerClose}
      title={
        <Header
          title="Pregled poruke"
          reference={selectedOrder?.localReference}
          status={headerStatus}
          customerStp={rawOrder?.customerStp ?? rawOrder?.stp}
          lockBadge={lockBadge}
          onClose={handleDrawerClose}
        />
      }
      width={1192}
      placement="right"
      forceRender
      maskClosable={false}
      destroyOnClose={false}
      closable={false}
      rootClassName={drawerStyles.drawerRoot}
      className={drawerStyles.drawer}
      contentWrapperStyle={{ maxWidth: "100vw" }}
    >
      <div ref={drawerNotificationHostRef} className={drawerStyles.drawerNotificationHost}>
        {drawerNotificationContext}
      </div>
      <div className={drawerStyles.contentContainer}>
        <Tabs activeTab={activeTab} onChange={setActiveTab} />

        <div className={styles.tabContent}>
          <div className={styles.infoLayout}>
            <div className={styles.leftColumn}>
              {activeTab === "history" ? (
                <History historyEntries={historyEntries} />
              ) : (
                <Information selectedOrder={selectedOrder} rawOrder={rawOrder} />
              )}

              <Notice
                notes={notes}
                suspiciousFlag={detailsDraft?.suspiciousFlag ?? rawOrder?.suspiciousFlag}
                canEditSuspiciousFlag={canEditDetails}
                onToggleSuspiciousFlag={handleSuspiciousFlagToggle}
                onAddNote={handleAddNote}
                isSavingNote={isSavingNote}
                canAddNote={
                  Boolean(transactionId) &&
                  canModifyData &&
                  !isArchivedTransaction &&
                  !isLockLoading &&
                  !isLockBlocked
                }
                selectedOrderKey={selectedOrderKey}
              />
            </div>

            <Details
              rawOrder={rawOrder}
              validationErrors={validationErrors}
              onReturnForCorrection={handleReturnForCorrection}
              onForceProcessing={handleForceProcessing}
              onSendForVerification={handleSendForVerification}
              onApproveVerification={handleApproveVerification}
              onRestoreFromError={handleRestoreFromError}
              onSendForVerificationReject={handleSendForVerificationReject}
              onDetailsDraftChange={handleDetailsDraftChange}
              transactionStatusCode={transactionStatusCode}
              canEditDetails={canEditDetails}
              actionPermissions={actionPermissions}
              actionsDisabled={actionsDisabled}
              isReturning={activeAction === "returnForCorrection"}
              isForcing={activeAction === "forceProcessing"}
              isSendingForVerification={activeAction === "sendForVerification"}
              isApprovingVerification={activeAction === "approveVerification"}
              isRestoringFromError={activeAction === "restoreFromError"}
              isSendingForVerificationReject={activeAction === "sendForVerificationReject"}
            />
          </div>
        </div>
      </div>

      <Modal
        open={isRejectModalOpen}
        title={t("common:rejectReasonModalTitle", {
          defaultValue: "Odbijanje transakcije",
        })}
        onCancel={closeRejectModal}
        onOk={handleRejectModalConfirm}
        okText={t("common:confirm", { defaultValue: "Potvrdi" })}
        cancelText={t("common:cancel", { defaultValue: "Odustani" })}
        okButtonProps={{ loading: activeAction === "sendForVerificationReject" }}
        destroyOnClose={false}
      >
        <div style={{ marginBottom: 8 }}>
          {t("common:rejectReason", { defaultValue: "Razlog odbijanja" })}
        </div>
        <Select
          style={{ width: "100%" }}
          showSearch
          value={selectedRejectCode}
          onChange={(value) => setSelectedRejectCode(value)}
          options={rejectOptions}
          loading={isLoadingRejects}
          disabled={isLoadingRejects || activeAction === "sendForVerificationReject"}
          placeholder={t("common:rejectReasonPlaceholder", {
            defaultValue: "Izaberite razlog odbijanja",
          })}
          optionFilterProp="label"
        />
      </Modal>
    </AntDrawer>
  );
};

export default Drawer;

