  if (isPresent(explicitText)) return String(explicitText);

  const action = entry?.action;
  const actionLabel = resolveHistoryActionLabel(action);
  const changes = normalizeHistoryChanges(entry);
  const changeKeys = Object.keys(changes);
  if (changeKeys.length > 0) {
    if (
      isPresent(actionLabel) &&
      ACTIONS_WITHOUT_CHANGE_DETAILS.has(String(action || "").trim().toUpperCase())
    ) {
      return String(actionLabel);
    }

    const fields = new Set();
    changeKeys.forEach((key) => {
      if (key.endsWith("_from")) {
        fields.add(key.slice(0, -5));
      } else if (key.endsWith("_to")) {
        fields.add(key.slice(0, -3));
      } else {
        fields.add(key);
      }
    });

    const changeText = Array.from(fields)
      .map((fieldName) => {
        const fromKey = `${fieldName}_from`;
        const toKey = `${fieldName}_to`;
        const hasFrom = Object.prototype.hasOwnProperty.call(changes, fromKey);
        const hasTo = Object.prototype.hasOwnProperty.call(changes, toKey);

        if (hasFrom || hasTo) {
          return `${formatHistoryFieldName(fieldName)}: ${formatHistoryValue(
            changes[fromKey]
          )} -> ${formatHistoryValue(changes[toKey])}`;
        }

        return `${formatHistoryFieldName(fieldName)}: ${formatHistoryValue(
          changes[fieldName]
        )}`;
      })
      .join(" | ");

    if (isPresent(actionLabel)) {
      return `${actionLabel}: ${changeText}`;
    }
    return changeText;
  }

  const valueFrom = entry?.valueFrom ?? entry?.oldValue ?? entry?.from;
  const valueTo = entry?.valueTo ?? entry?.newValue ?? entry?.to;
  if (isPresent(actionLabel) && (isPresent(valueFrom) || isPresent(valueTo))) {
    return `${actionLabel}: ${asText(valueFrom)} -> ${asText(valueTo)}`;
  }
  if (isPresent(actionLabel)) return String(actionLabel);

  const field = entry?.field ?? entry?.property;
  const oldValue = valueFrom;
  const newValue = valueTo;

  if (isPresent(field) && (isPresent(oldValue) || isPresent(newValue))) {
    return `Izmena polja ${field}: ${asText(oldValue)} -> ${asText(newValue)}`;
  }

  return "Izmena";
