import {
  ALL_ORDERS,
  COMPLAINTS,
  DASHBOARD,
  INCOMING,
  OUTGOING,
} from "../../components/routes";

const getInitials = (fullName) => {
  if (!fullName) return "";
  return fullName
    .split(" ")
    .map((part) => part.trim())
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0].toUpperCase())
    .join("");
};

const Sidebar = ({ t }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [transactionType, setTransactionType] = useState("incoming");

