import React, { useCallback, useEffect, useMemo, useState } from "react";
import { withTranslation } from "react-i18next";
import { useLocation } from "react-router-dom";
import Header from "../../parts/header/Header";
import DataTable from "../../components/DataTable/DataTable";
import Notification from "../../components/Notification/Notification";
import columns, {
  BOOKING_FEE_COLUMN_VISIBILITY_STORAGE_KEY,
  BOOKING_FEE_DEFAULT_VISIBLE_COLUMN_KEYS,
} from "./columns";
import {
  executePrepared,
  getAll as getAllBookingFees,
  retryBookingError,
  retryCalcError,
  retryEnrichError,
} from "../../services/bookingFeeService/service";
import {
  BOOKING_FEE,
  BOOKING_FEE_BOOKED,
  BOOKING_FEE_ENRICHED,
  BOOKING_FEE_ERROR,
  BOOKING_FEE_PREPARED,
} from "../../components/routes";

const BOOKING_FEE_SEARCH_KEYS = [
  "requestId",
  "callReplyRef",
  "bookingStatus",
  "updatedBy",
  "updatedAt",
  "messageType",
  "direction",
  "segment",
  "creditorAgent",
  "creditorLrc",
  "debtorLrc",
  "crStatisticalCode",
  "currency",
  "budgetCode",
  "transactionCode",
  "opu",
];

const BOOKING_FEE_ROUTE_SETTINGS = [
  {
    path: BOOKING_FEE_BOOKED,
    titleKey: "sidebar:bookingFeeBooked",
    titleDefault: "Booked",
    matchesStatus: (status) => status === "BOOKED",
  },
  {
    path: BOOKING_FEE_PREPARED,
    titleKey: "sidebar:bookingFeePrepared",
    titleDefault: "Prepared",
    matchesStatus: (status) => status === "PREPARED",
  },
  {
    path: BOOKING_FEE_ENRICHED,
    titleKey: "sidebar:bookingFeeEnriched",
    titleDefault: "Enriched",
    matchesStatus: (status) => status === "ENRICHED",
  },
  {
    path: BOOKING_FEE_ERROR,
    titleKey: "sidebar:bookingFeeError",
    titleDefault: "Error",
    matchesStatus: (status) => status.includes("ERROR"),
  },
  {
    path: BOOKING_FEE,
    titleKey: "sidebar:bookingFee",
    titleDefault: "Booking fee",
    matchesStatus: () => true,
  },
];

const normalizePath = (path) => {
  if (!path) return "";
  if (path.length > 1 && path.endsWith("/")) return path.slice(0, -1);
  return path;
};

const resolveRouteSettings = (pathname) => {
  const normalizedPath = normalizePath(pathname);
  const matchedRoute = BOOKING_FEE_ROUTE_SETTINGS.find(
    (route) => normalizePath(route.path) === normalizedPath
  );
  return matchedRoute || BOOKING_FEE_ROUTE_SETTINGS[0];
};

const normalizeBookingStatus = (value) => String(value ?? "").trim().toUpperCase();

const BookingFeeBase = ({ t }) => {
  const location = useLocation();
  const routeSettings = useMemo(
    () => resolveRouteSettings(location.pathname),
    [location.pathname]
  );
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [actionLoadingByRef, setActionLoadingByRef] = useState({});

  const fetchBookingFees = useCallback(
    async (options = {}) => {
      const { showLoading = false } = options;

      if (showLoading) {
        setLoading(true);
      }

      try {
        const response = await getAllBookingFees();
        const nextItems = Array.isArray(response?.data) ? response.data : [];
        setItems(nextItems);
      } catch (error) {
        Notification(
          t("common:errorTitle", { defaultValue: "Greska" }),
          error?.response?.data?.message ||
            t("notification:bookingFee:loadFailed", {
              defaultValue: "Neuspesno ucitavanje booking fee podataka.",
            }),
          "error",
          "topRight"
        );
      } finally {
        if (showLoading) {
          setLoading(false);
        }
      }
    },
    [t]
  );

  useEffect(() => {
    if (top !== self) {
      top.location = self.location;
    }

    void fetchBookingFees({ showLoading: true });
  }, [fetchBookingFees]);

  const handleReload = useCallback(() => {
    void fetchBookingFees({ showLoading: true });
  }, [fetchBookingFees]);

  const handleRowAction = useCallback(
    async (record, actionType) => {
      const callReplyRef = String(record?.callReplyRef ?? "").trim();
      if (!callReplyRef || !actionType) {
        return;
      }

      const actionByType = {
        execute: {
          run: executePrepared,
          successMessage: t("notification:bookingFee:executeSuccess", {
            defaultValue: "Booking je uspesno pokrenut za referencu {{ref}}.",
            ref: callReplyRef,
          }),
        },
        "retry-enrich": {
          run: retryEnrichError,
          successMessage: t("notification:bookingFee:retryEnrichSuccess", {
            defaultValue: "Ponovno obogacivanje je uspesno pokrenuto za referencu {{ref}}.",
            ref: callReplyRef,
          }),
        },
        "retry-calc": {
          run: retryCalcError,
          successMessage: t("notification:bookingFee:retryCalcSuccess", {
            defaultValue: "Ponovni obracun je uspesno pokrenut za referencu {{ref}}.",
            ref: callReplyRef,
          }),
        },
        "retry-booking": {
          run: retryBookingError,
          successMessage: t("notification:bookingFee:retryBookingSuccess", {
            defaultValue: "Ponovno knjizenje je uspesno pokrenuto za referencu {{ref}}.",
            ref: callReplyRef,
          }),
        },
      };

      const selectedAction = actionByType[actionType];
      if (!selectedAction) {
        return;
      }

      setActionLoadingByRef((current) => ({
        ...current,
        [callReplyRef]: true,
      }));

      try {
        await selectedAction.run(callReplyRef);
        Notification(
          t("common:confirmTitle", { defaultValue: "Potvrda" }),
          selectedAction.successMessage,
          "success",
          "topRight"
        );
        await fetchBookingFees({ showLoading: false });
      } catch (error) {
        Notification(
          t("common:errorTitle", { defaultValue: "Greska" }),
          error?.response?.data?.message ||
            t("notification:bookingFee:actionFailed", {
              defaultValue: "Neuspesno izvrsavanje booking fee akcije.",
            }),
          "error",
          "topRight"
        );
      } finally {
        setActionLoadingByRef((current) => {
          const next = { ...current };
          delete next[callReplyRef];
          return next;
        });
      }
    },
    [fetchBookingFees, t]
  );

  const filteredItems = useMemo(
    () =>
      items.filter((item) =>
        routeSettings.matchesStatus(normalizeBookingStatus(item?.bookingStatus))
      ),
    [items, routeSettings]
  );

  const tableColumns = useMemo(
    () =>
      columns(t, {
        onRowAction: handleRowAction,
        actionLoadingByRef,
      }),
    [actionLoadingByRef, handleRowAction, t]
  );

  return (
    <>
      <Header
        title={t(routeSettings.titleKey, {
          defaultValue: routeSettings.titleDefault,
        })}
      />
      <DataTable
        items={filteredItems}
        loading={loading}
        rowKey="id"
        searchKeys={BOOKING_FEE_SEARCH_KEYS}
        columns={tableColumns}
        onReload={handleReload}
        showExportButton={false}
        columnVisibilityStorageKey={BOOKING_FEE_COLUMN_VISIBILITY_STORAGE_KEY}
        defaultVisibleColumnKeys={BOOKING_FEE_DEFAULT_VISIBLE_COLUMN_KEYS}
      />
    </>
  );
};

export default withTranslation(["privatePage", "sidebar", "notification"])(
  BookingFeeBase
);

