import React from "react";
import { Button, Tooltip } from "antd";
import { PlayCircleOutlined, ReloadOutlined } from "@ant-design/icons";
import styles from "../../components/DataTable/DataTable.module.css";

export const BOOKING_FEE_COLUMN_VISIBILITY_STORAGE_KEY =
  "CBR_COLUMN_VISIBILITY:booking-fee:v4";

export const BOOKING_FEE_DEFAULT_VISIBLE_COLUMN_KEYS = [
  "requestId",
  "callReplyRef",
  "bookingStatus",
  "messageType",
  "direction",
  "segment",
  "creditorAgent",
  "creditorLrc",
  "debtorLrc",
  "crStatisticalCode",
  "amount",
  "amountRsd",
  "middrate",
  "fee",
  "currency",
  "creditAccount",
  "debitAccount",
  "budgetCode",
  "transactionCode",
  "narrative1",
  "narrative2",
  "opu",
  "reportingDate",
  "valueDate",
  "updatedBy",
  "updatedAt",
];

const formatAmount = (value) => {
  if (value === null || value === undefined || value === "") {
    return "-";
  }

  const numericValue = Number(value);
  if (Number.isNaN(numericValue)) {
    return String(value);
  }

  return numericValue.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 8,
  });
};

const formatText = (value) => {
  const normalized = String(value ?? "").trim();
  return normalized || "-";
};

const resolveRowAction = (record, t) => {
  const status = String(record?.bookingStatus ?? "").trim().toUpperCase();

  if (status === "PREPARED") {
    return {
      type: "execute",
      tooltip: t("common:executeBooking", { defaultValue: "Execute booking" }),
      icon: <PlayCircleOutlined />,
    };
  }

  if (status === "ENRICH_ERROR") {
    return {
      type: "retry-enrich",
      tooltip: t("common:retryEnrich", { defaultValue: "Retry enrich" }),
      icon: <ReloadOutlined />,
    };
  }

  if (status === "CALC_ERROR") {
    return {
      type: "retry-calc",
      tooltip: t("common:retryCalc", { defaultValue: "Retry calc" }),
      icon: <ReloadOutlined />,
    };
  }

  if (status === "BOOKING_ERROR") {
    return {
      type: "retry-booking",
      tooltip: t("common:retryBooking", { defaultValue: "Retry booking" }),
      icon: <ReloadOutlined />,
    };
  }

  return null;
};

const bookingFeeColumns = (
  t,
  { onRowAction, actionLoadingByRef = {} } = {}
) => [
  {
    title: t("columns:requestId", { defaultValue: "Request ID" }),
    dataIndex: "requestId",
