  },
  {
    title: t("columns:callReplyRef", { defaultValue: "Call reply ref" }),
    dataIndex: "callReplyRef",
    key: "callReplyRef",
    width: 180,
    render: formatText,
  },
  {
    title: t("columns:bookingStatus", { defaultValue: "Booking status" }),
    dataIndex: "bookingStatus",
    key: "bookingStatus",
    width: 160,
    render: formatText,
  },
  {
    title: t("columns:messageType", { defaultValue: "Message type" }),
    dataIndex: "messageType",
    key: "messageType",
    width: 140,
    render: formatText,
  },
  {
    title: t("columns:direction", { defaultValue: "Direction" }),
    dataIndex: "direction",
    key: "direction",
    width: 120,
    render: formatText,
  },
  {
    title: t("columns:segment", { defaultValue: "Segment" }),
    dataIndex: "segment",
    key: "segment",
    width: 180,
    render: formatText,
  },
  {
    title: t("columns:creditorAgent", { defaultValue: "Creditor bank BIC" }),
    dataIndex: "creditorAgent",
    key: "creditorAgent",
    width: 170,
    render: formatText,
  },
  {
    title: t("columns:creditorLrc", { defaultValue: "Creditor LRC" }),
    dataIndex: "creditorLrc",
    key: "creditorLrc",
    width: 160,
    render: formatText,
  },
  {
    title: t("columns:debtorLrc", { defaultValue: "Debtor LRC" }),
    dataIndex: "debtorLrc",
    key: "debtorLrc",
    width: 160,
    render: formatText,
  },
  {
    title: t("columns:crStatisticalCode", { defaultValue: "CR statistical code" }),
    dataIndex: "crStatisticalCode",
    key: "crStatisticalCode",
    width: 170,
    render: formatText,
  },
  {
    title: t("columns:amount", { defaultValue: "Amount" }),
    dataIndex: "amount",
    key: "amount",
    width: 140,
    align: "right",
    render: formatAmount,
  },
  {
    title: t("columns:amountRsd", { defaultValue: "Amount RSD" }),
    dataIndex: "amountRsd",
    key: "amountRsd",
    width: 140,
    align: "right",
    render: formatAmount,
  },
  {
    title: t("columns:middrate", { defaultValue: "Middrate" }),
    dataIndex: "middrate",
    key: "middrate",
    width: 140,
    align: "right",
    render: formatAmount,
  },
  {
    title: t("columns:fee", { defaultValue: "Fee" }),
    dataIndex: "fee",
    key: "fee",
    width: 120,
    align: "right",
    render: formatAmount,
  },
  {
    title: t("columns:currency", { defaultValue: "Currency" }),
    dataIndex: "currency",
    key: "currency",
    width: 110,
    render: formatText,
