// ColumnSearchProps.js
import React from "react";
import { Input, Button, Space } from "antd";
import { FilterOutlined } from "@ant-design/icons";
import Highlighter from "react-highlight-words";
import styles from "./ColumnSearchProps.module.css";

const ColumnSearchProps = ({
  t,
  dataIndex,
  label,
  searchText,
  searchedColumn,
  setSearchText,
  setSearchedColumn,
  searchInput,
}) => {
  const resolvedSearchInput = searchInput || { current: null };
  const translate = t || ((_, options) => options?.defaultValue ?? "");
  const resolvedLabel = label || dataIndex;

  const handleSearch = (selectedKeys, confirm) => {
    confirm();
    setSearchText(selectedKeys[0] || "");
    setSearchedColumn(dataIndex);
  };

  const handleReset = (clearFilters) => {
    clearFilters();
    setSearchText("");
    setSearchedColumn("");
  };

  return {
    filterDropdown: ({
      setSelectedKeys,
      selectedKeys,
      confirm,
      clearFilters,
    }) => (
      <div style={{ padding: 8 }} onKeyDown={(e) => e.stopPropagation()}>
        <Input
          ref={resolvedSearchInput}
          placeholder={translate("common:filterPlaceholder", {
            defaultValue: "Filter {{column}}",
            column: resolvedLabel,
          })}
          value={selectedKeys[0]}
          onChange={(e) =>
            setSelectedKeys(e.target.value ? [e.target.value] : [])
          }
          onPressEnter={() => handleSearch(selectedKeys, confirm)}
          className={styles.filterInput}
          style={{ marginBottom: 8, display: "block" }}
        />
        <Space>
          <Button
            type="default"
            onClick={() => handleSearch(selectedKeys, confirm)}
            icon={<FilterOutlined />}
            size="small"
            style={{ width: 90 }}
            className={styles.filterButton}
          >
            {translate("common:filter", { defaultValue: "Filter" })}
          </Button>
          <Button
            onClick={() => clearFilters && handleReset(clearFilters)}
            size="small"
            style={{ width: 90 }}
            className={styles.resetButton}
          >
            {translate("common:reset", { defaultValue: "Reset" })}
          </Button>
          {/*<Button
            type="link"
            size="small"
            onClick={() => {
              confirm({ closeDropdown: false });
              setLocalSearchText(selectedKeys[0]);
              setSearchedColumn(dataIndex);
            }}
          >
            Filter
          </Button>*/}

       { /* <Button type="link" size="small" onClick={() => close()}>
            Close
          </Button> */}
        </Space>
      </div>
    ),
    filterIcon: (filtered) => (
      <FilterOutlined style={{ color: filtered ? "#082245" : undefined }} />
    ),
    onFilter: (value, record) =>
      String(record[dataIndex] ?? "")
        .toLowerCase()
        .includes(String(value ?? "").toLowerCase()),
    onFilterDropdownOpenChange: (visible) => {
      if (visible) {
        setTimeout(() => resolvedSearchInput.current?.select(), 100);
      }
    },
    render: (text) =>
      searchedColumn === dataIndex ? (
        <Highlighter
          highlightStyle={{ backgroundColor: "#ffc069", padding: 0 }}
          searchWords={searchText ? [searchText] : []}
          autoEscape
          textToHighlight={text ? text.toString() : ""}
        />
      ) : (
        text
      ),
  };
};

export default ColumnSearchProps;

