import React from "react";
import { Button, Tooltip } from "antd";
import {
  CheckCircleOutlined,
  ExclamationCircleOutlined,
  EyeOutlined,
} from "@ant-design/icons";
import ColumnSearchProps from "../../components/ColumnSearchProps/ColumnSearchProps";
import styles from "../../components/DataTable/DataTable.module.css";
import { resolveStatusPresentation } from "../../utils/statusPresentation";

const EMPTY_VALUE = "-";
const BASE_TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY =
  "CBR_COLUMN_VISIBILITY_V6:reference|status|grpSts|coreId|debtorCoreId|orderingPartyName|settlementAmount|settlementDate|currency|userName|receivedDate|p8Reference|stp|contract|entryBy|reworkBy";
const SUSPICIOUS_FLAG_COLUMN_KEY = "suspiciousFlag";

export const TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY_WITH_SUSPICIOUS =
  "CBR_COLUMN_VISIBILITY_V6:reference|status|suspiciousFlag|grpSts|coreId|debtorCoreId|orderingPartyName|settlementAmount|settlementDate|currency|userName|receivedDate|p8Reference|stp|contract|entryBy|reworkBy";
export const TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY_WITHOUT_SUSPICIOUS =
  BASE_TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY;

const BASE_TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS = [
  "reference",
  "status",
  "grpSts",
  "coreId",
  "debtorCoreId",
  "orderingPartyName",
  "settlementAmount",
  "settlementDate",
  "currency",
  "userName",
  "receivedDate",
  "p8Reference",
];
export const TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS_WITH_SUSPICIOUS = [
  "reference",
  "status",
  SUSPICIOUS_FLAG_COLUMN_KEY,
  ...BASE_TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS.filter(
    (key) => key !== "reference" && key !== "status"
  ),
];
export const TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS_WITHOUT_SUSPICIOUS =
  BASE_TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS;
export const TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY =
  TRANSACTION_COLUMN_VISIBILITY_STORAGE_KEY_WITH_SUSPICIOUS;
export const TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS =
  TRANSACTION_DEFAULT_VISIBLE_COLUMN_KEYS_WITH_SUSPICIOUS;

const formatAmount = (value) => {
  if (value === null || value === undefined || value === "") return "-";
  const number = Number(value);
  if (Number.isNaN(number)) return String(value);
  return number.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

const renderStatusIcon = (tone) =>
  tone === "success" ? (
    <CheckCircleOutlined className={styles.statusIcon} />
  ) : (
    <ExclamationCircleOutlined className={styles.statusIcon} />
  );

const resolveGrpStsPresentation = (value, t) => {
  const normalized = String(value || "").trim().toUpperCase();

  if (normalized === "ACCP") {
    return t("common:grpStsAccepted", { defaultValue: "Prihvacen" });
  }

  if (normalized === "RJCT") {
    return t("common:grpStsRejected", { defaultValue: "Odbijen" });
  }

  return String(value || "").trim() || "-";
};

const isGrpRejected = (value) => String(value || "").trim().toUpperCase() === "RJCT";

const isSuspiciousFlagHighlighted = (value) => {
  const normalized = String(value || "").trim().toUpperCase();
  return ["DA", "YES", "Y", "TRUE", "1"].includes(normalized);
};

const isIncomingRecord = (record = {}) =>
  String(record?.direction ?? record?._raw?.direction ?? "")
    .trim()
    .toUpperCase() === "IN";

const resolveSuspiciousFlagDisplayValue = (value, record = {}) => {
  if (!isIncomingRecord(record)) {
    return EMPTY_VALUE;
  }

  return String(value || "").trim() || EMPTY_VALUE;
};

const getColumnSearchProps = (
  dataIndex,
  label,
  searchText,
  searchedColumn,
  setSearchText,
  setSearchedColumn,
  searchInput,
  t
) =>
  ColumnSearchProps({
    t,
    dataIndex,
    label,
    searchText,
    searchedColumn,
    setSearchText,
    setSearchedColumn,
    searchInput,
  });

