import React, { useEffect, useMemo, useState } from "react";
import { HistoryOutlined } from "@ant-design/icons";
import styles from "./Drawer.module.css";

const COLLAPSED_TEXT_LENGTH = 220;
const MAX_VISIBLE_HISTORY_ITEMS = 4;

const History = ({ historyEntries }) => {
  const [expandedMap, setExpandedMap] = useState({});
  const [showAllEntries, setShowAllEntries] = useState(false);
  const hasHistory = Array.isArray(historyEntries) && historyEntries.length > 0;
  const normalizedEntries = Array.isArray(historyEntries) ? historyEntries : [];
  const hasHiddenEntries = normalizedEntries.length > MAX_VISIBLE_HISTORY_ITEMS;

  useEffect(() => {
    setShowAllEntries(false);
  }, [historyEntries]);

  const visibleEntries = useMemo(() => {
    if (showAllEntries || !hasHiddenEntries) {
      return normalizedEntries;
    }
    return normalizedEntries.slice(0, MAX_VISIBLE_HISTORY_ITEMS);
  }, [showAllEntries, hasHiddenEntries, normalizedEntries]);

  const toggleExpanded = (entryId) => {
    setExpandedMap((current) => ({
      ...current,
      [entryId]: !current[entryId],
    }));
  };

  const renderHistorySegment = (segment, index) => {
    const normalizedSegment = String(segment || "").trim();
    if (!normalizedSegment.includes("->")) {
      return <span key={`segment-${index}`}>{normalizedSegment}</span>;
    }

    const [leftSideRaw, rightSideRaw] = normalizedSegment.split("->");
    const leftSide = String(leftSideRaw || "").trim();
    const rightSide = String(rightSideRaw || "").trim();

    let prefix = "";
    let oldValue = leftSide;

    const fromMatch = leftSide.match(/^(.*\bfrom\s+)(.+)$/i);
    if (fromMatch) {
      prefix = fromMatch[1];
      oldValue = fromMatch[2];
    } else {
      const lastColonIndex = leftSide.lastIndexOf(":");
      if (lastColonIndex >= 0) {
        prefix = `${leftSide.slice(0, lastColonIndex + 1)} `;
        oldValue = leftSide.slice(lastColonIndex + 1).trim();
      }
    }

    return (
      <span key={`segment-${index}`}>
        <span className={styles.historyLead}>{prefix}</span>
        <span className={styles.historyOld}>{oldValue}</span>
        <span className={styles.historyArrow}> to </span>
        <span className={styles.historyNew}>{rightSide}</span>
      </span>
    );
  };

  const renderHistoryText = (text) => {
    const normalizedText = String(text || "");
    const segments = normalizedText.split(" | ");

    if (segments.length === 1) {
      return renderHistorySegment(segments[0], 0);
    }

    return segments.map((segment, index) => (
      <React.Fragment key={`fragment-${index}`}>
        {index > 0 && <span className={styles.historySegmentSeparator}> | </span>}
        {renderHistorySegment(segment, index)}
      </React.Fragment>
    ));
  };

  return (
    <section className={styles.panel}>
      <h3 className={styles.panelTitle}>Istorija izmena</h3>

      <div className={styles.historyList}>
        <h4 className={styles.historySectionLabel}>Izmene</h4>

        {hasHistory && hasHiddenEntries && (
          <button
            type="button"
            className={`${styles.historyToggle} ${styles.historyListToggle}`.trim()}
            onClick={() => setShowAllEntries((current) => !current)}
          >
            {showAllEntries
              ? "Prikazi manje"
              : `Prikazi sve (${normalizedEntries.length})`}
          </button>
        )}

        {!hasHistory && <p className={styles.historyText}>Nema istorije izmena.</p>}

        {hasHistory &&
          visibleEntries.map((entry) => {
            const text = entry?.text || "";
            const canExpand = text.length > COLLAPSED_TEXT_LENGTH;
            const isExpanded = Boolean(expandedMap[entry.id]);

            return (
              <article key={entry.id} className={styles.historyItem}>
                <div className={styles.historyIconWrap}>
                  <HistoryOutlined className={styles.historyIcon} />
                </div>

                <div className={styles.historyContent}>
                  <div className={styles.historyMeta}>
                    <span className={styles.historyAuthor}>{entry.author}</span>
                    <span className={styles.historyDate}>{entry.date}</span>
                  </div>

                  <p
                    className={`${styles.historyText} ${
                      canExpand && !isExpanded ? styles.historyTextCollapsed : ""
                    }`.trim()}
                  >
                    {renderHistoryText(text)}
                  </p>

                  {canExpand && (
                    <button
                      type="button"
                      className={styles.historyToggle}
                      onClick={() => toggleExpanded(entry.id)}
                    >
                      {isExpanded ? "Prikazi manje" : "Prikazi vise"}
                    </button>
                  )}
                </div>
              </article>
            );
          })}
      </div>
    </section>
  );
};

export default History;

