          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Creditor ID</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>{asText(rawOrder?.creditorCoreId)}</span>
          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Creditor agent BIC</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>{asText(rawOrder?.creditorAgent)}</span>
          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Adresa</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>
              {asText(rawOrder?.creditorAddress ?? rawOrder?.creditorPostalAddress)}
            </span>
            <span className={styles.detailValueSub}>
              {formatAddress(rawOrder?.creditorTown, rawOrder?.creditorCountry)}
            </span>
          </div>
        </div>
      </div>

      <p className={styles.groupLabel}>SETTLEMENT</p>
      <div className={styles.detailsRows}>
        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Amount</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>
              {formatSettlementAmount(
                rawOrder?.settlementAmount ?? selectedOrder?.settlementAmount,
                rawOrder?.settlementCurrency ?? selectedOrder?.currency ?? "EUR"
              )}
            </span>
          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Processing date</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>
              {formatDate(
                rawOrder?.createdAt ??
                  rawOrder?.sourceReceivedAt ??
                  rawOrder?.settlementDate
              )}
            </span>
          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Remittance info</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>{asText(rawOrder?.remittanceInfo)}</span>
          </div>
        </div>

        <div className={styles.detailRow}>
          <span className={styles.detailLabel}>Message type</span>
          <div className={styles.detailValueWrap}>
            <span className={styles.detailValueMain}>
              {formatMessageTypeLabel(messageType)}
            </span>
          </div>
        </div>

        {shouldShowSkipperResponse ? (
          <div className={styles.detailRow}>
            <span className={styles.detailLabel}>
              {t("columns:skipperResponseType", {
                defaultValue: "Skipper odgovor",
              })}
            </span>
            <div className={styles.detailValueWrap}>
              <span className={styles.detailValueMain}>
                {asText(
                  rawOrder?.skipperResponseType ??
                    selectedOrder?.skipperResponseType
                )}
              </span>
            </div>
          </div>
        ) : null}

        {messageType === "P4" ? (
          <div className={styles.detailRow}>
            <span className={styles.detailLabel}>Linked pacs.008</span>
            <div className={styles.detailValueWrap}>
              <span className={styles.detailValueMain}>
                {asText(rawOrder?.p8Reference ?? selectedOrder?.p8Reference)}
              </span>
            </div>
          </div>
        ) : null}
      </div>
    </section>
  );
};

