package rs.unicredit.cbr.service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;

import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnClass;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import rs.unicredit.cbr.dto.GlFeeEnrichmentResponse;
import rs.unicredit.cbr.dto.GlFeePrepareDataResponse;
import rs.unicredit.cbr.model.GlFeeData;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@Service
@RequiredArgsConstructor
@ConditionalOnProperty(prefix = "customs.services.gl-fee-prepare-data", name = "enabled", havingValue = "true")
@ConditionalOnClass(name = "com.ibm.as400.access.AS400JDBCDriver")
public class GlFeeEnrichmentService {

    private static final Logger LOG = LoggerFactory.getLogger(GlFeeEnrichmentService.class);
    private static final String STATUS_NEW = "NEW";
    private static final String STATUS_ENRICHING = "ENRICHING";
    private static final String STATUS_ENRICHED = "ENRICHED";
    private static final String STATUS_ENRICH_ERROR = "ENRICH_ERROR";

    private final GlFeeDataRepository glFeeDataRepository;
    private final GlFeePrepareDataService glFeePrepareDataService;
    private final GlFeeAuditActorService glFeeAuditActorService;

    public int enrichNewRows() {
        List<GlFeeData> candidates = glFeeDataRepository.findAllByBookingStatusOrderByIdAsc(STATUS_NEW);
        int enrichedCount = 0;
        for (GlFeeData candidate : candidates) {
            if (candidate == null || candidate.getId() == null) {
                continue;
            }
            if (enrichSingle(candidate, STATUS_NEW)) {
                enrichedCount++;
            }
        }
        LOG.info("GL fee enrichment completed candidates={} enriched={}", candidates.size(), enrichedCount);
        return enrichedCount;
    }

    public GlFeeEnrichmentResponse retryEnrichError(String callReplyRef) {
        String normalizedCallReplyRef = normalizeString(callReplyRef);
        if (normalizedCallReplyRef == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "callReplyRef is required");
        }

        GlFeeData feeData = glFeeDataRepository.findByCallReplyRef(normalizedCallReplyRef)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "GL fee data not found for callReplyRef=" + normalizedCallReplyRef));

        if (!STATUS_ENRICH_ERROR.equalsIgnoreCase(normalizeString(feeData.getBookingStatus()))) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "GL fee data is not in ENRICH_ERROR status for callReplyRef=" + normalizedCallReplyRef
                            + ", currentStatus=" + feeData.getBookingStatus());
        }

        boolean success = enrichSingle(feeData, STATUS_ENRICH_ERROR);
        GlFeeData refreshed = glFeeDataRepository.findById(feeData.getId())
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.INTERNAL_SERVER_ERROR,
                        "GL fee data disappeared after enrichment retry for callReplyRef=" + normalizedCallReplyRef));
        if (!success) {
            throw new ResponseStatusException(
                    HttpStatus.BAD_GATEWAY,
                    "GL fee enrichment retry failed for callReplyRef=" + normalizedCallReplyRef
                            + ", currentStatus=" + refreshed.getBookingStatus());
        }

        return GlFeeEnrichmentResponse.builder()
                .feeDataId(refreshed.getId())
                .requestId(refreshed.getRequestId())
                .callReplyRef(refreshed.getCallReplyRef())
                .bookingStatus(feeData.getBookingStatus())
                .nextBookingStatus(refreshed.getBookingStatus())
                .opu(refreshed.getOpu())
                .amount(refreshed.getAmount())
                .amountRsd(refreshed.getAmountRsd())
                .debitAccount(refreshed.getDebitAccount())
                .middrate(refreshed.getMiddrate())
                .sdc(refreshed.getSdc())
                .build();
    }

    private boolean enrichSingle(GlFeeData candidate, String expectedStatus) {
        LocalDateTime now = LocalDateTime.now();
        String actor = glFeeAuditActorService.resolveActorOrSystem();
        int claimed = glFeeDataRepository.updateBookingStatus(
                candidate.getId(),
                expectedStatus,
                STATUS_ENRICHING,
                actor,
                now,
                now);
        if (claimed == 0) {
            LOG.info(
                    "Skipping GL fee enrichment for feeDataId={} callReplyRef={} because row was already claimed from status={}",
                    candidate.getId(),
                    candidate.getCallReplyRef(),
                    expectedStatus);
            return false;
        }

        try {
            GlFeePrepareDataResponse response = glFeePrepareDataService.fetchByInRef(candidate.getCallReplyRef());
            Map<String, Object> row = extractSingleRow(response, candidate);
            String opu = normalizeString(row.get("FEEOPU"));
            BigDecimal amount = toBigDecimal(row.get("BOOKAMT"));
            Long debitAccount = toLong(row.get("FEEACC"));
            BigDecimal middrate = toBigDecimal(row.get("MIDDRATE"));
            Integer sdc = toInteger(row.get("SDC"));
            BigDecimal amountRsd = calculateAmountRsd(amount, middrate);
            int updated = glFeeDataRepository.updateEnrichmentResult(
                    candidate.getId(),
                    STATUS_ENRICHING,
                    STATUS_ENRICHED,
                    opu,
                    amount,
                    amountRsd,
                    debitAccount,
                    middrate,
                    sdc,
                    actor,
                    LocalDateTime.now(),
                    LocalDateTime.now());
            LOG.info(
                    "GL fee enrichment success feeDataId={} callReplyRef={} opu={} amount={} amountRsd={} debitAccount={} middrate={} sdc={} updatedRows={}",
                    candidate.getId(),
                    candidate.getCallReplyRef(),
                    opu,
                    amount,
                    amountRsd,
                    debitAccount,
                    middrate,
                    sdc,
                    updated);
            return updated > 0;
        } catch (Exception ex) {
            glFeeDataRepository.updateBookingStatus(
                    candidate.getId(),
                    STATUS_ENRICHING,
                    STATUS_ENRICH_ERROR,
                    actor,
                    LocalDateTime.now(),
                    LocalDateTime.now());
            LOG.error(
                    "GL fee enrichment failed feeDataId={} callReplyRef={}: {}",
                    candidate.getId(),
                    candidate.getCallReplyRef(),
                    ex.getMessage(),
                    ex);
            return false;
        }
    }

    private Map<String, Object> extractSingleRow(GlFeePrepareDataResponse response, GlFeeData candidate) {
        if (response == null || response.getRows() == null || response.getRows().isEmpty()) {
            throw new IllegalStateException(
                    "GET_FEEACCOUNT returned no rows for callReplyRef=" + candidate.getCallReplyRef());
        }
        if (response.getRows().size() > 1) {
            LOG.warn(
                    "GET_FEEACCOUNT returned multiple rows for feeDataId={} callReplyRef={}, using first row",
                    candidate.getId(),
                    candidate.getCallReplyRef());
        }
        return response.getRows().getFirst();
    }

    private String normalizeString(Object value) {
        if (value == null) {
            return null;
        }
        String trimmed = String.valueOf(value).trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private Long toLong(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Number number) {
            return number.longValue();
        }
        String text = normalizeString(value);
        return text == null ? null : new BigDecimal(text).longValue();
    }

    private Integer toInteger(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Number number) {
            return number.intValue();
        }
        String text = normalizeString(value);
        return text == null ? null : Integer.valueOf(text);
    }

    private BigDecimal toBigDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof BigDecimal bigDecimal) {
            return bigDecimal;
        }
        if (value instanceof Number number) {
            return BigDecimal.valueOf(number.doubleValue());
        }
        String text = normalizeString(value);
        return text == null ? null : new BigDecimal(text);
    }

    private BigDecimal calculateAmountRsd(BigDecimal amount, BigDecimal middrate) {
        if (amount == null || middrate == null) {
            return null;
        }
        return amount.multiply(middrate).setScale(2, RoundingMode.HALF_UP);
    }
}

