    @Column(name = "APPLIED_FEE_RULE_NO")
    private Integer appliedFeeRuleNo;

    @Column(name = "BUDGET_CODE", length = 20)
    private String budgetCode;

    @Column(name = "TRANSACTION_CODE", length = 20)
    private String transactionCode;

    @Column(name = "CURRENCY", length = 10)
    private String currency;

    @Column(name = "NARRATIVE1", length = 35)
    private String narrative1;

    @Column(name = "NARRATIVE2", length = 35)
