     WHERE EXISTS (
            SELECT 1
              FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
             WHERE c.gl_fee_data_id = a.id
     );

    IF v_verified_fee_count != v_candidate_fee_count THEN
        RAISE_APPLICATION_ERROR(
                -20021,
