CREATE OR REPLACE PROCEDURE CBR.SP_ARCHIVE_GL_FEE_DATA(
    p_days_old                  IN NUMBER DEFAULT 10,
    p_archived_fee_rows         OUT NUMBER,
    p_archived_booking_log_rows OUT NUMBER,
    p_deleted_fee_rows          OUT NUMBER,
    p_deleted_booking_log_rows  OUT NUMBER
)
IS
    v_candidate_fee_count NUMBER := 0;
    v_candidate_log_count NUMBER := 0;
    v_verified_fee_count  NUMBER := 0;
    v_verified_log_count  NUMBER := 0;
BEGIN
    IF p_days_old IS NULL OR p_days_old < 0 THEN
        RAISE_APPLICATION_ERROR(-20020, 'p_days_old must be zero or positive');
    END IF;

    p_archived_fee_rows := 0;
    p_archived_booking_log_rows := 0;
    p_deleted_fee_rows := 0;
    p_deleted_booking_log_rows := 0;

    DELETE FROM CBR.GTT_GL_FEE_ARCHIVE_CAND;

    INSERT INTO CBR.GTT_GL_FEE_ARCHIVE_CAND (
        GL_FEE_DATA_ID,
        CALL_REPLY_REF,
        BOOKED_AT
    )
    SELECT g.id,
           g.call_reply_ref,
           g.status_updated_at
      FROM CBR.TBL_GL_FEE_DATA g
     WHERE g.booking_status = 'BOOKED'
       AND g.status_updated_at < SYSTIMESTAMP - NUMTODSINTERVAL(p_days_old, 'DAY');

    v_candidate_fee_count := SQL%ROWCOUNT;

    IF v_candidate_fee_count = 0 THEN
        RETURN;
    END IF;

    SELECT COUNT(*)
      INTO v_candidate_log_count
      FROM CBR.TBL_GL_FEE_BOOKING_LOG l
     WHERE EXISTS (
            SELECT 1
              FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
             WHERE c.gl_fee_data_id = l.gl_fee_data_id
     );

    INSERT INTO CBR.TBL_GL_FEE_DATA_ARCHIVE
    SELECT g.*,
           SYSTIMESTAMP AS archived_at
      FROM CBR.TBL_GL_FEE_DATA g
     WHERE EXISTS (
            SELECT 1
              FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
             WHERE c.gl_fee_data_id = g.id
     )
       AND NOT EXISTS (
            SELECT 1
              FROM CBR.TBL_GL_FEE_DATA_ARCHIVE a
             WHERE a.id = g.id
     );

    p_archived_fee_rows := SQL%ROWCOUNT;

    SELECT COUNT(*)
      INTO v_verified_fee_count
      FROM CBR.TBL_GL_FEE_DATA_ARCHIVE a
     WHERE EXISTS (
            SELECT 1
              FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
             WHERE c.gl_fee_data_id = a.id
     );

    IF v_verified_fee_count != v_candidate_fee_count THEN
        RAISE_APPLICATION_ERROR(
                -20021,
                'GL fee archive verification failed. candidates=' || v_candidate_fee_count
                || ', archived=' || v_verified_fee_count);
    END IF;

    INSERT INTO CBR.TBL_GL_FEE_BOOKING_LOG_ARCHIVE
    SELECT l.*,
           SYSTIMESTAMP AS archived_at
      FROM CBR.TBL_GL_FEE_BOOKING_LOG l
     WHERE EXISTS (
            SELECT 1
              FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
             WHERE c.gl_fee_data_id = l.gl_fee_data_id
     )
       AND NOT EXISTS (
            SELECT 1
              FROM CBR.TBL_GL_FEE_BOOKING_LOG_ARCHIVE a
             WHERE a.id = l.id
     );

    p_archived_booking_log_rows := SQL%ROWCOUNT;

    SELECT COUNT(*)
      INTO v_verified_log_count
      FROM CBR.TBL_GL_FEE_BOOKING_LOG_ARCHIVE a
     WHERE EXISTS (
            SELECT 1
              FROM CBR.TBL_GL_FEE_BOOKING_LOG l
             WHERE l.id = a.id
               AND EXISTS (
                    SELECT 1
                      FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
                     WHERE c.gl_fee_data_id = l.gl_fee_data_id
               )
     );

    IF v_verified_log_count != v_candidate_log_count THEN
        RAISE_APPLICATION_ERROR(
                -20022,
                'GL fee booking log archive verification failed. candidates=' || v_candidate_log_count
                || ', archived=' || v_verified_log_count);
    END IF;

    DELETE FROM CBR.TBL_GL_FEE_BOOKING_LOG l
     WHERE EXISTS (
            SELECT 1
              FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
             WHERE c.gl_fee_data_id = l.gl_fee_data_id
     );

    p_deleted_booking_log_rows := SQL%ROWCOUNT;

    IF p_deleted_booking_log_rows != v_candidate_log_count THEN
        RAISE_APPLICATION_ERROR(
                -20023,
                'GL fee booking log delete verification failed. candidates=' || v_candidate_log_count
                || ', deleted=' || p_deleted_booking_log_rows);
    END IF;

    DELETE FROM CBR.TBL_GL_FEE_DATA g
     WHERE EXISTS (
            SELECT 1
              FROM CBR.GTT_GL_FEE_ARCHIVE_CAND c
             WHERE c.gl_fee_data_id = g.id
     );

    p_deleted_fee_rows := SQL%ROWCOUNT;

    IF p_deleted_fee_rows != v_candidate_fee_count THEN
        RAISE_APPLICATION_ERROR(
                -20024,
                'GL fee delete verification failed. candidates=' || v_candidate_fee_count
                || ', deleted=' || p_deleted_fee_rows);
    END IF;

    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
