import rs.unicredit.cbr.repository.CbrFeeMatrixRepository;
import rs.unicredit.cbr.repository.GlFeeDataRepository;

@Service
@RequiredArgsConstructor
public class GlFeeQueryService {

    private final GlFeeDataRepository glFeeDataRepository;
    private final CbrFeeMatrixRepository cbrFeeMatrixRepository;

    @Transactional(readOnly = true)
    public List<GlFeeListItemDto> getAll() {
        Map<Integer, String> feeRuleNamesByRuleNo = loadFeeRuleNamesByRuleNo();

        return glFeeDataRepository.findAll(Sort.by(Sort.Direction.DESC, "id"))
                .stream()
                .map(entity -> toDto(entity, feeRuleNamesByRuleNo))
                .toList();
    }

    private Map<Integer, String> loadFeeRuleNamesByRuleNo() {
        Map<Integer, String> ruleNamesByRuleNo = new LinkedHashMap<>();

        cbrFeeMatrixRepository.findAll(Sort.by(Sort.Direction.DESC, "id"))
                .forEach(rule -> putRuleNameIfAbsent(ruleNamesByRuleNo, rule));

        return ruleNamesByRuleNo;
    }

    private void putRuleNameIfAbsent(Map<Integer, String> ruleNamesByRuleNo, CbrFeeMatrix rule) {
        if (rule == null || rule.getRuleNo() == null) {
            return;
        }

        String normalizedRuleName = normalize(rule.getRuleName());
        if (normalizedRuleName == null) {
            return;
        }

        ruleNamesByRuleNo.putIfAbsent(rule.getRuleNo(), normalizedRuleName);
    }

    private GlFeeListItemDto toDto(GlFeeData entity, Map<Integer, String> feeRuleNamesByRuleNo) {
        Integer appliedFeeRuleNo = entity.getAppliedFeeRuleNo();

        return GlFeeListItemDto.builder()
                .id(entity.getId())
                .requestId(entity.getRequestId())
                .callReplyRef(entity.getCallReplyRef())
                .messageType(entity.getMessageType())
                .direction(entity.getDirection())
                .segment(entity.getSegment())
                .creditorAgent(entity.getCreditorAgent())
                .creditorLrc(entity.getCreditorLrc())
                .debtorLrc(entity.getDebtorLrc())
                .crStatisticalCode(entity.getCrStatisticalCode())
                .amount(entity.getAmount())
                .amountRsd(entity.getAmountRsd())
                .middrate(entity.getMiddrate())
                .sdc(entity.getSdc())
                .creditAccount(entity.getCreditAccount())
                .debitAccount(entity.getDebitAccount())
                .fee(entity.getFee())
                .appliedFeeRuleNo(appliedFeeRuleNo)
                .appliedFeeRuleName(feeRuleNamesByRuleNo.get(appliedFeeRuleNo))
                .budgetCode(entity.getBudgetCode())
                .transactionCode(entity.getTransactionCode())
                .currency(entity.getCurrency())
                .narrative1(entity.getNarrative1())
                .narrative2(entity.getNarrative2())
                .opu(entity.getOpu())
                .reportingDate(entity.getReportingDate())
                .valueDate(entity.getValueDate())
                .bookingStatus(entity.getBookingStatus())
                .updatedBy(entity.getUpdatedBy())
                .updatedAt(entity.getUpdatedAt())
                .build();
    }

    private String normalize(String value) {
        if (value == null) {
            return null;
        }

        String normalized = value.trim();
        return normalized.isEmpty() ? null : normalized;
    }
}

