import React from "react";
import { Button, Tooltip } from "antd";
import { PlayCircleOutlined, ReloadOutlined } from "@ant-design/icons";
import styles from "../../components/DataTable/DataTable.module.css";
import ColumnSearchProps from "../../components/ColumnSearchProps/ColumnSearchProps";

export const BOOKING_FEE_COLUMN_VISIBILITY_STORAGE_KEY =
  "CBR_COLUMN_VISIBILITY:booking-fee:v6";

export const BOOKING_FEE_DEFAULT_VISIBLE_COLUMN_KEYS = [
  "requestId",
  "callReplyRef",
  "bookingStatus",
  "appliedFeeRuleName",
  "messageType",
  "direction",
  "segment",
  "creditorAgent",
  "creditorLrc",
  "debtorLrc",
  "crStatisticalCode",
  "amount",
  "amountRsd",
  "middrate",
  "fee",
  "currency",
  "creditAccount",
  "debitAccount",
  "budgetCode",
  "transactionCode",
  "narrative1",
  "narrative2",
  "opu",
  "reportingDate",
  "valueDate",
  "ref",
  "updatedBy",
  "updatedAt",
];

const formatAmount = (value) => {
  if (value === null || value === undefined || value === "") {
    return "-";
  }

  const numericValue = Number(value);
  if (Number.isNaN(numericValue)) {
    return String(value);
  }

  return numericValue.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 8,
  });
};

const formatText = (value) => {
  const normalized = String(value ?? "").trim();
  return normalized || "-";
};

const getColumnSearchProps = (
  dataIndex,
  label,
  searchText,
  searchedColumn,
  setSearchText,
  setSearchedColumn,
  searchInput,
  t
) =>
  ColumnSearchProps({
    t,
    dataIndex,
    label,
    searchText,
    searchedColumn,
    setSearchText,
    setSearchedColumn,
    searchInput,
  });

const buildSearchableTextColumn = ({
  t,
  searchText,
  searchedColumn,
  setSearchText,
  setSearchedColumn,
  searchInput,
  dataIndex,
  titleKey,
  defaultTitle,
  width,
}) => ({
  title: t(`columns:${titleKey}`, { defaultValue: defaultTitle }),
  dataIndex,
  key: dataIndex,
  width,
  sorter: (a, b) =>
    String(a?.[dataIndex] ?? "").localeCompare(String(b?.[dataIndex] ?? "")),
  render: formatText,
  ...getColumnSearchProps(
    dataIndex,
    t(`columns:${titleKey}`, { defaultValue: defaultTitle }),
    searchText,
    searchedColumn,
    setSearchText,
    setSearchedColumn,
    searchInput,
    t
  ),
});

const resolveRowAction = (record, t) => {
  const status = String(record?.bookingStatus ?? "").trim().toUpperCase();

  if (status === "PREPARED") {
    return {
      type: "execute",
      tooltip: t("common:executeBooking", { defaultValue: "Execute booking" }),
      icon: <PlayCircleOutlined />,
    };
  }

  if (status === "ENRICH_ERROR") {
    return {
      type: "retry-enrich",
      tooltip: t("common:retryEnrich", { defaultValue: "Retry enrich" }),
      icon: <ReloadOutlined />,
    };
  }

  if (status === "CALC_ERROR") {
    return {
      type: "retry-calc",
      tooltip: t("common:retryCalc", { defaultValue: "Retry calc" }),
      icon: <ReloadOutlined />,
    };
  }

